<?php
declare(strict_types=1);
require __DIR__ . '/auth.php'; requireAdmin(); require ROOT_PATH . '/includes/mailer.php';
$db=database();$legacy=databaseUsesLegacySchema();$notice='';$error='';
$posts=$legacy?$db->query('SELECT id,title,slug,excerpt,date FROM posts WHERE published IN (1,2) ORDER BY date DESC')->fetchAll():$db->query("SELECT id,title,slug,excerpt,published_at AS date FROM wts_posts WHERE status='published' ORDER BY published_at DESC")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){
  verifyCsrf();$postId=(int)($_POST['post_id']??0);$post=null;foreach($posts as $candidate)if((int)$candidate['id']===$postId)$post=$candidate;
  $customSubject=trim((string)($_POST['subject']??''));$customBody=trim((string)($_POST['body']??''));
  if((!$post&&!$customSubject)||!isset($_POST['confirm_send']))$error='Choose a reflection or write a custom email subject, then confirm the send.';elseif(!smtpConfigured())$error='SMTP is not configured. Save working SMTP settings before sending a campaign.';else{
    $recipients=$legacy?$db->query("SELECT id,email FROM email_subscribers WHERE status='active'")->fetchAll():$db->query("SELECT id,email FROM wts_subscribers WHERE status='active'")->fetchAll();$sent=0;$failed=0;
    foreach($recipients as $recipient){$token=bin2hex(random_bytes(32));try{if($legacy)$db->prepare('UPDATE email_subscribers SET unsubscribe_token_hash=? WHERE id=?')->execute([hash('sha256',$token),$recipient['id']]);else $db->prepare('UPDATE wts_subscribers SET token=? WHERE id=?')->execute([hash('sha256',$token),$recipient['id']]);$postUrl=$post?applicationUrl('blog/post.php?slug='.rawurlencode($post['slug'])):'';$unsubscribeUrl=applicationUrl('unsubscribe.php?id='.rawurlencode((string)$recipient['id']).'&token='.rawurlencode($token));$subject=$customSubject?:$post['title'].' | Word Truth Spirit';$message=$customBody?nl2br(e($customBody)):'<h2>'.e($post['title']).'</h2><p>'.e($post['excerpt']).'</p>'; $html='<p>Word Truth Spirit update</p>'.$message.($postUrl?'<p><a href="'.e($postUrl).'">Read more</a></p>':'').'<hr><p style="font-size:12px">You are receiving this because you subscribed to Word Truth Spirit. <a href="'.e($unsubscribeUrl).'">Unsubscribe</a></p>';if(smtpSend($recipient['email'],$subject,$html))$sent++;else $failed++;}catch(Throwable $exception){$failed++;}}
    if($legacy&&databaseTableExists('notification_campaigns'))$db->prepare('INSERT INTO notification_campaigns (id,post_id,channel,sent_count,failed_count) VALUES (?,?,?,?,?)')->execute([uuidV4(),$postId,'email',$sent,$failed]);
    $notice="Campaign complete: {$sent} delivered, {$failed} failed.";
  }
}
$history=$legacy&&databaseTableExists('notification_campaigns')?$db->query("SELECT n.sent_count,n.failed_count,n.created_at,p.title FROM notification_campaigns n LEFT JOIN posts p ON p.id=n.post_id WHERE n.channel='email' ORDER BY n.created_at DESC LIMIT 12")->fetchAll():[];
$adminTitle='Email campaigns';$currentAdminPage='campaigns';require __DIR__.'/_header.php';
?>
<header class="admin-title"><div><p class="kicker">Reader updates</p><h1>Email campaigns</h1><p>Send a published reflection to confirmed subscribers, with a secure unsubscribe link added to every message.</p></div></header>
<?php if($notice):?><p class="notice success"><?=e($notice)?></p><?php endif;?><?php if($error):?><p class="notice error"><?=e($error)?></p><?php endif;?>
<section class="admin-panel campaign-panel"><form method="post" onsubmit="return confirm('Send this campaign to every active subscriber?')"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><label>Reflection or subscriber update<select name="post_id"><option value="">Write a custom email below…</option><?php foreach($posts as $post):?><option value="<?= (int)$post['id'] ?>"><?=e($post['title'])?> · <?=date('M j, Y',strtotime($post['date']))?></option><?php endforeach;?></select></label><label>Custom email subject<input name="subject" placeholder="Ministry update"></label><label>Custom email message<textarea name="body" rows="8" placeholder="Write a personal email to all subscribers…"></textarea></label><p>Selecting a reflection uses its title and excerpt. A custom subject/message lets you send a standalone email to every active subscriber.</p><label class="toggle-label"><input type="checkbox" name="confirm_send" value="1" required> I am ready to send this to all active subscribers.</label><button class="button button-primary">Send campaign</button></form></section>
<?php if($history):?><section class="admin-panel campaign-history"><h2>Recent delivery history</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Reflection</th><th>Delivered</th><th>Failed</th><th>Sent</th></tr></thead><tbody><?php foreach($history as $item):?><tr><td><?=e($item['title']?:'Archived reflection')?></td><td><?= (int)$item['sent_count']?></td><td><?= (int)$item['failed_count']?></td><td><?=date('M j, Y g:i a',strtotime($item['created_at']))?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
